#include "engine/editor_prefab.hpp"
#include "engine/mesh_component.hpp"
#include "engine/light_component.hpp"
#include "engine/editor_play.hpp"
#include <iostream>
using namespace engine;
namespace {
void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
template<class F>void rejects(F fn){bool threw=false;try{fn();}catch(const std::exception&){threw=true;}check(threw,"Expected rejection");}
std::shared_ptr<const PrefabAsset> fixture(){Actor actor("Lantern");actor.setSavedId("lantern-root");auto& mesh=actor.addComponent<MeshComponent>("Body",Mesh::cube());mesh.setSavedId("lantern-body");mesh.color={.2f,.5f,.7f};auto& light=actor.addComponent<LightComponent>("Glow",LightType::Point);light.setSavedId("lantern-glow");light.intensity=4;return PrefabAsset::capture(actor,"Lantern");}
Node* keyed(Actor& instance,const std::string& key){auto* link=instance.getComponent<PrefabInstanceComponent>();for(auto& b:link->bindings())if(b.key==key)return instance.findSavedNode(b.node);return nullptr;}
void persistence(){
 auto asset=fixture();Scene scene;auto a=asset->instantiate(),b=asset->instantiate();const auto aid=a->savedId(),bid=b->savedId();scene.adoptChild(std::move(a));scene.adoptChild(std::move(b));scene.synchronize();
 auto& aa=*static_cast<Actor*>(scene.findSavedNode(aid));auto& bb=*static_cast<Actor*>(scene.findSavedNode(bid));check(aa.id()!=bb.id(),"Independent instance handles");check(static_cast<MeshComponent*>(keyed(aa,"lantern-body"))->mesh==static_cast<MeshComponent*>(keyed(bb,"lantern-body"))->mesh,"Shared immutable mesh");
 auto file=PrefabAssetArchive::save(asset);auto loaded=PrefabAssetArchive::load(file);check(loaded->id()==asset->id()&&loaded->definition().savedId()=="lantern-root","Prefab file identity");file.back()^=std::byte{1};rejects([&]{PrefabAssetArchive::load(file);});
 auto doc=SceneArchive::load(SceneArchive::save(scene));auto* restored=static_cast<Actor*>(doc.scene->findSavedNode(aid));auto* link=restored->getComponent<PrefabInstanceComponent>();check(link->asset()->id()==asset->id(),"Scene retains prefab asset link");
 check(static_cast<MeshComponent*>(keyed(*restored,"lantern-body"))->mesh==static_cast<const MeshComponent*>(link->asset()->definition().findSavedNode("lantern-body"))->mesh,"Archive shares resources across definition and instances");
 auto duplicate=SceneArchive::duplicateSubtree(*restored);auto& da=static_cast<Actor&>(*duplicate);check(keyed(da,"lantern-body")&&keyed(da,"lantern-body")->savedId()!=keyed(*restored,"lantern-body")->savedId(),"Duplicate remaps instance bindings");
 const auto deletedId=keyed(*restored,"lantern-glow")->savedId();auto deleted=restored->detachChild(*keyed(*restored,"lantern-glow"));
 auto missingDuplicate=SceneArchive::duplicateSubtree(*restored);auto& missing=static_cast<Actor&>(*missingDuplicate);check(!keyed(missing,"lantern-glow"),"Duplicate preserves a locally deleted definition node");
 for(const auto& binding:missing.getComponent<PrefabInstanceComponent>()->bindings())if(binding.key=="lantern-glow")check(binding.node!=deletedId,"Duplicate remaps deleted-node binding identity");
 PrefabAssetEditor changed(asset);changed.session().select("lantern-body");changed.session().setProperty("mesh.color.1",.8);auto revised=changed.snapshot("Lantern");EditorSession duplicateEditor(*doc.scene);const auto missingId=missing.savedId();doc.scene->adoptChild(std::move(missingDuplicate));const std::array revision={revised};check(duplicateEditor.updatePrefabs(revision),"Duplicated deletion can receive an upstream update");check(!keyed(*static_cast<Actor*>(doc.scene->findSavedNode(missingId)),"lantern-glow"),"Update preserves duplicated deletion override");
 EditorPlaySession play;play.start(scene,{});check(play.scene()->findSavedNode(aid),"Play clone retains link");play.stop();
}
void propagate(){
 auto asset=fixture();Scene scene;EditorSession editor(scene);check(editor.placePrefab(asset,{-2,0,0}),"Place prefab");const auto first=editor.selected()->savedId();check(editor.placePrefab(asset,{2,0,0}),"Place second prefab");const auto second=editor.selected()->savedId();
 auto* actor=static_cast<Actor*>(scene.findSavedNode(first));editor.select(keyed(*actor,"lantern-body")->savedId());editor.setProperty("mesh.color.0",.9);editor.select(first);check(prefabOverrides(*actor,*EditorPropertyRegistry::builtins()).size()>=2,"Overrides list includes placement/tint");
 PrefabAssetEditor document(asset);document.session().select("lantern-glow");document.session().setProperty("light.intensity",12.);auto next=document.snapshot("Lantern");const auto before=SceneArchive::save(scene);const std::array updates={next};check(editor.updatePrefabs(updates),"Update instances");
 auto test=[&](const std::string& id,float x,float red){auto& a=*static_cast<Actor*>(scene.findSavedNode(id));check(a.transform.position.x==x,"Instance placement preserved");check(static_cast<MeshComponent*>(keyed(a,"lantern-body"))->color.x==red,"Local tint preserved");check(static_cast<LightComponent*>(keyed(a,"lantern-glow"))->intensity==12,"Unoverridden light propagated");};
 test(first,-2,.9f);test(second,2,.2f);const auto after=SceneArchive::save(scene);check(editor.undo()&&SceneArchive::save(scene)==before,"Atomic propagation undo");check(editor.redo()&&SceneArchive::save(scene)==after,"Atomic propagation redo");
 editor.select(first);check(editor.updatePrefabs(updates,true),"Revert selected overrides");check(static_cast<MeshComponent*>(keyed(*static_cast<Actor*>(scene.findSavedNode(first)),"lantern-body"))->color.x==.2f,"Revert restores source tint");check(editor.undo(),"Revert undo");check(editor.unpackPrefab(),"Unpack instance");check(!static_cast<Actor*>(scene.findSavedNode(first))->hasComponent<PrefabInstanceComponent>(),"Unpack retains objects");check(editor.undo(),"Unpack undo");
 auto restored=SceneArchive::load(SceneArchive::save(scene));EditorSession reopened(*restored.scene);PrefabAssetEditor doc2(next);doc2.session().select("lantern-glow");doc2.session().setProperty("light.intensity",20.);const std::array newer={doc2.snapshot("Lantern")};check(reopened.updatePrefabs(newer),"Update after scene reopen");
}
void variantsAndStructure(){
 auto asset=fixture();auto variant=PrefabAsset::capture(asset->definition(),"Red lantern",{},1,asset);PrefabAssetEditor variantDoc(variant);variantDoc.session().select("lantern-body");variantDoc.session().setProperty("mesh.color.0",1.);variant=variantDoc.snapshot("Red lantern");
 PrefabAssetEditor baseDoc(asset);baseDoc.session().select("lantern-glow");baseDoc.session().setProperty("light.intensity",16.);auto newBase=baseDoc.snapshot("Lantern");variant=rebasePrefab(variant,newBase,*EditorPropertyRegistry::builtins());check(static_cast<const MeshComponent*>(variant->definition().findSavedNode("lantern-body"))->color.x==1,"Variant tint preserved on rebase");check(static_cast<const LightComponent*>(variant->definition().findSavedNode("lantern-glow"))->intensity==16,"Variant inherits new base");
 auto loaded=PrefabAssetArchive::load(PrefabAssetArchive::save(variant));check(loaded->base()&&loaded->base()->id()==asset->id(),"Variant base chain roundtrip");
 auto local=prefabDefinition(asset->definition());static_cast<LightComponent*>(local->findSavedNode("lantern-glow"))->intensity=8;auto incoming=prefabDefinition(asset->definition());auto removed=incoming->detachChild(*incoming->findSavedNode("lantern-glow"));rejects([&]{mergePrefab(asset->definition(),*local,*incoming,*EditorPropertyRegistry::builtins());});
 local=prefabDefinition(asset->definition());local->addComponent<Component>("Local helper").setSavedId("local-helper");incoming=prefabDefinition(newBase->definition());incoming->addComponent<Component>("Added upstream").setSavedId("new-helper");auto merged=mergePrefab(asset->definition(),*local,*incoming,*EditorPropertyRegistry::builtins());check(merged->findSavedNode("new-helper")&&merged->findSavedNode("local-helper"),"Local and upstream additions preserved");
 // One conflicting instance must preserve the entire scene and history.
 Scene scene;EditorSession editor(scene);editor.placePrefab(asset);auto first=editor.selected()->savedId();editor.placePrefab(asset);auto second=editor.selected()->savedId();auto* a=static_cast<Actor*>(scene.findSavedNode(second));static_cast<LightComponent*>(keyed(*a,"lantern-glow"))->intensity=22;const auto before=SceneArchive::save(scene);const auto count=editor.undoCount();auto deletion=prefabDefinition(asset->definition());auto child=deletion->detachChild(*deletion->findSavedNode("lantern-glow"));auto removedAsset=PrefabAsset::create(std::move(deletion),asset->name(),asset->id(),2);const std::array updates={removedAsset};rejects([&]{editor.updatePrefabs(updates);});check(SceneArchive::save(scene)==before&&editor.undoCount()==count,"Conflict publishes no partial instances");
 rejects([&]{PrefabAsset::capture(*static_cast<Actor*>(scene.findSavedNode(first)),"Cycle",asset->id(),2,asset);});
}
}
int main(){try{persistence();propagate();variantsAndStructure();std::cout<<"Prefab asset tests passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
